xmlDocPtr page = xmlNewDoc(BAD_CAST "1.0");               /* stage 1: logical page */
xmlNodePtr inv = xmlNewNode(NULL, BAD_CAST "invoice");
xmlDocSetRootElement(page, inv);
xmlNewProp(inv, BAD_CAST "total", BAD_CAST "42.00");
xmlNewChild(inv, NULL, BAD_CAST "customer", BAD_CAST "ACME");

xsltStylesheetPtr xsl = xsltParseStylesheetFile(BAD_CAST "invoice-html.xsl");
xmlDocPtr out = xsltApplyStylesheet(xsl, page, NULL);       /* stage 2: render */
xsltSaveResultToFile(stdout, out, xsl);
xsltFreeStylesheet(xsl); xmlFreeDoc(out); xmlFreeDoc(page);
